const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];

export const runScenario = (scenario: Scenario): ScenarioOutcome => {
  const totalBasePremium = scenario.steps[0].items.reduce(
    (total, item) => total + basePremiumOf(item),
    0,
  );
  const premium =
    roundUpToWholeGold(totalBasePremium * FIRST_INSURANCE_SURCHARGE) +
    PROCESSING_FEE;
  return { results: [{ premium }] };
};

